test "the OUTBOUND half (MES-16) still rides every request's _meta" do
  {:ok, client} =
    Client.start_link(
      transport: {MockTransport, []},
      client_capabilities: %ClientCapabilities{
        extensions: %{"com.example/ext" => %{"setting" => true}}
      }
    )

  transport = Client.transport(client)
  {_result, request} = discover(client, transport, %{"tools" => %{}})

  assert request["params"]["_meta"]["io.modelcontextprotocol/clientCapabilities"][
           "extensions"
         ] == %{"com.example/ext" => %{"setting" => true}}
end

test "the retry re-stamps the version chosen from `supported`" do
  # The client advertises something the server rejects; the server offers
  # 2026-07-28, which we do support, so the retry must carry THAT version
  # in `_meta` — not the originally-configured one.
  {client, transport} = start_client(protocol_version: "2026-07-28")

  task = Task.async(fn -> Client.list_tools(client) end)
  [first] = wait_for_sent(transport, 1)

  assert first["params"]["_meta"]["io.modelcontextprotocol/protocolVersion"] == "2026-07-28"

  MockTransport.inject(transport, %{
    "jsonrpc" => "2.0",
    "id" => first["id"],
    "error" => %{
      "code" => -32_022,
      "message" => "Unsupported protocol version",
      "data" => %{"supported" => ["2026-07-28"], "requested" => "2026-07-28"}
    }
  })

  [_first, retry] = wait_for_sent(transport, 2)

  MockTransport.inject(transport, %{
    "jsonrpc" => "2.0",
    "id" => retry["id"],
    "result" => %{"tools" => []}
  })

  assert {:ok, %{"tools" => []}} = Task.await(task)
end

test "from_map/1 handles experimental capabilities" do
  map = %{"experimental" => %{"custom" => %{"enabled" => true}}}
  caps = ServerCapabilities.from_map(map)
  assert caps.experimental == %{"custom" => %{"enabled" => true}}
end

test "a NESTED object property IS reachable — every step is a `properties` key" do
  annotations =
    annotations!(
      schema(%{
        "outer" =>
          schema(%{
            "inner" => %{"type" => "string", "x-mcp-header" => "Inner"}
          })
      })
    )

  assert [%{name: "Inner", path: ["outer", "inner"]}] = annotations

  assert [{"mcp-param-inner", "v"}] =
           HeaderMirror.headers_for(annotations, %{"outer" => %{"inner" => "v"}})
end
